/**
 * shared/pax-capabilities.ts — the Pax capability inventory (PP-1).
 *
 * One row per top-level case label of BOTH Pax dispatch switches
 * (executeTool in server/ai/tools.ts, executeSupportTool in
 * server/ai/supportAgent.ts). This file is DATA ONLY — no server imports —
 * so it stays browser-safe.
 *
 * The row is NOT a second authority for anything an existing registry
 * already holds: group/domain/dispatch come from TOOL_REGISTRY
 * (shared/pax-controls.ts), scope from INTENT_META / SUPPORT_TOOL_SCOPES,
 * approval from APPROVAL_REQUIRED_TOOLS, pause-safety from
 * PAUSE_SAFE_TOOLS / PAUSE_SAFE_SUPPORT_TOOLS, and role membership from
 * BOTH bundle maps (legacy getToolsForRole in server/ai/tools.ts and
 * roleAllowList in server/services/appIntents/index.ts, the map the Pax
 * loop actually consumes). tests/unit/paxCapabilityInventory.test.ts
 * ASSERTS agreement with every one of those sources; the row carries
 * only what no registry holds (receipt mode, coverage contract, family,
 * objects, the RW memo row, and the date the family landed).
 *
 * Rows are written one per line in JSON-compatible literal form so
 * scripts/pax-capability-inventory.mjs can generate
 * docs/compliance/pax-capability-inventory.md without a TS loader.
 */

import type { PaxRecordDomain, PaxToolDispatch, PaxToolGroup } from "./pax-controls";

export type PaxReceiptMode = "none" | "generic_hook" | "own" | "witnessed";
export type PaxCoverageKind = "n/a" | "single_slice" | "two_book";

export interface CapabilityRow {
  dispatch: PaxToolDispatch;
  group: PaxToolGroup;
  domain?: PaxRecordDomain;
  /** The permission-ladder scope the source registry declares, or null. */
  scope: string | null;
  approvalRequired: boolean;
  pauseSafe: boolean;
  receipt: PaxReceiptMode;
  coverage: PaxCoverageKind;
  /** Required whenever coverage is not "n/a": what the read does NOT cover. */
  notCovered?: string;
  /** The vertical or platform area this capability serves. */
  family: string;
  /** The object family the tool acts on. */
  objects: string[];
  /** The RW memo row (files/pax-real-work-experience-2026-11.md §1), when one applies. */
  rwRow?: string;
  /** Roles whose bundle contains this tool, in BOTH bundle maps; [] for support tools. */
  roles: string[];
  /** ISO date the tool's family landed; for pre-inventory tools, the inventory date. */
  since: string;
}

